// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";
import {IAccessControl} from "../src/TimelockController.sol";
import {IERC165} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 x) public {
        // Wide domain: the fuzzed value selects which interface id is queried.
        // With probability 2/3 the query targets one of the two registered ERC-165
        // interface ids (IERC165's or IAccessControl's); otherwise an arbitrary
        // fuzzed id is used. No vm.assume narrows the space.
        uint256 r = x % 3;
        bytes4 id;
        if (r == 0) {
            id = type(IERC165).interfaceId;
        } else if (r == 1) {
            id = type(IAccessControl).interfaceId;
        } else {
            id = bytes4(uint32(x));
        }

        // General rule: for every admissible query, if the queried id is one of
        // the two registered interface ids, the contract must report support.
        // The reference (disjunction) always returns true for both registered ids.
        // The mutant (conjunction) returns false for both registered ids, so the
        // assertion breaks for roughly 2/3 of the fuzzed inputs.
        assertTrue(r >= 2 || c.supportsInterface(id));
    }
}
